const PADDING = 2;
const drawingWidth = drawing => Math.max(...drawing.rows.map(row => row.length));

/** Lightweight, immutable picker metadata; no shared mutable grids. */
export const MOTIF_PRESETS = Object.freeze(DRAWINGS.map(drawing => Object.freeze({
  id: drawing.id,
  name: drawing.name,
  category: drawing.category,
  width: drawingWidth(drawing) + PADDING * 2,
  height: drawing.rows.length + PADDING * 2,
})));

export function getMotifPreset(id) {
  const drawing = DRAWINGS.find(item => item.id === id);
  if (!drawing) throw new RangeError('找不到这个内置图案。');
  const width = drawingWidth(drawing) + PADDING * 2;
  const height = drawing.rows.length + PADDING * 2;
  const background = drawing.colors['.'];
  const grid = Array.from({ length: height }, () => Array(width).fill(background));
  drawing.rows.forEach((row, y) => [...row].forEach((key, x) => {
    const color = drawing.colors[key];
    if (!color) throw new Error(`图案 ${id} 包含未定义颜色。`);
    grid[y + PADDING][x + PADDING] = color;
  }));
  const used = new Set(grid.flat());
  const palette = [background, ...Object.values(drawing.colors).filter(color => color !== background && used.has(color))];
  return { id: drawing.id, name: drawing.name, category: drawing.category, grid, palette };
}
